for k,x in enumerate(slow,54):add(k,*x,'input:self-lived',['slow'])
neutral=[('I took one concrete step and then stopped; I did not keep opening more alternatives.','direction','EN'),('Tôi đã thử một bước nhỏ rồi kết thúc, không tiếp tục mở thêm lựa chọn.','romantic','VI'),('I completed the next action myself rather than asking someone else to decide it.','family','EN'),('Toi da lam buoc tiep theo cu the va khong ne sang viec khac.','daily','VI_NO_DIACRITICS')]
for k,x in enumerate(neutral,57):add(k,*x,'input:self-lived',[])
batch_a=[c['case_id'] for c in cases if int(c['case_id'].split('S')[1])%2==1];batch_b=[c['case_id'] for c in cases if int(c['case_id'].split('S')[1])%2==0]
fixture={'authority':'V8.3.181 V1 SEALED EXECUTION FIXTURE','cases':cases,'batch_a':batch_a,'batch_b':batch_b}
selection={'authority':'V8.3.181 V1 OWNER SELECTION','batch_a':batch_a,'batch_b':batch_b}
membership={'authority':'V8.3.181 V1 SEALED MEMBERSHIP','all_case_ids':sorted(batch_a+batch_b),'batch_a':batch_a,'batch_b':batch_b}
keys=[]
for c in cases:
    e=c['expected'];key=(e['route'],tuple(e['families']),e['sequence'])
    if key not in keys:keys.append(key)
groups=[]
for i,key in enumerate(keys,1):
    r,f,s=key;groups.append({'group':f'G{i:02d}','case_ids':[c['case_id'] for c in cases if (c['expected']['route'],tuple(c['expected']['families']),c['expected']['sequence'])==key],'expected':{'route':r,'families':list(f),'sequence':s}})
gold={'authority':'V8.3.181 V1 INDEPENDENT GOLD','construction':'manual semantic contract; no V50R3 runtime consulted','groups':groups}
for n,o in [('V8_3_181_SEALED_EXECUTION_FIXTURE_V1.json',fixture),('V8_3_181_SEALED_SELECTION_V1.json',selection),('V8_3_181_SEALED_MEMBERSHIP_V1.json',membership),('V8_3_181_INDEPENDENT_GOLD_V1.json',gold)]: (root/n).write_text(json.dumps(o,ensure_ascii=False,indent=2))
